import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type OvenTimerProps = Record<string, any>;

const OvenTimer: React.FC<OvenTimerProps> = ({
  backgroundColor = "#152036",
  transparentBackground = false,
  panelColor = "#F4EFE6",
  textColor = "#121A2A",
  accentColor = "#D92D20",
  durationInSeconds = 8,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timings
  const entranceDuration = 40;
  const windUpStart = entranceDuration + 10;
  const windUpEnd = fps * durationInSeconds - 30;

  // Entrance Animation
  const panelYOffset = spring({
    frame,
    fps,
    config: { damping: 14, mass: 1.2 },
    durationInFrames: entranceDuration,
  });
  const panelY = interpolate(panelYOffset, [0, 1], [200 * s, 0]);
  const panelOpacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Winding Animation
  // Knob turns 360 degrees (representing setting 12 hours)
  const knobRotation = interpolate(
    frame,
    [windUpStart, windUpEnd],
    [0, 360],
    {
      easing: Easing.inOut(Easing.cubic),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Time formatting based on rotation (360 deg = 12 hours = 43200 seconds)
  const totalSeconds = interpolate(
    knobRotation,
    [0, 360],
    [0, 43200],
    { extrapolateRight: "clamp" }
  );

  const formatTime = (seconds: number) => {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const sec = Math.floor(seconds % 60);
    return `${h.toString().padStart(2, "0")}:${m.toString().padStart(
      2,
      "0"
    )}:${sec.toString().padStart(2, "0")}`;
  };

  const displayTime = formatTime(totalSeconds);

  // Dimensions
  const panelWidth = 760 * s;
  const panelHeight = 1360 * s;
  const dialSize = 580 * s;
  const knobSize = 440 * s;
  const knobHandleWidth = 60 * s;
  const knobHandleHeight = 340 * s;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* Main Panel */}
      <div
        style={{
          width: panelWidth,
          height: panelHeight,
          backgroundColor: panelColor,
          borderRadius: 60 * s,
          boxShadow: `0 ${30 * s}px ${60 * s}px rgba(0,0,0,0.25), inset 0 ${4 * s}px ${8 * s}px rgba(255,255,255,0.7), inset 0 -${4 * s}px ${10 * s}px rgba(0,0,0,0.05)`,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          paddingTop: 80 * s,
          paddingBottom: 60 * s,
          transform: `translateY(${panelY}px)`,
          opacity: panelOpacity,
          position: "relative",
          boxSizing: "border-box",
        }}
      >
        {/* Title */}
        <div
          style={{
            fontSize: 64 * s,
            fontWeight: 800,
            color: textColor,
            letterSpacing: 3 * s,
            marginBottom: 40 * s,
          }}
        >
          OVEN TIMER
        </div>

        {/* Top Label & Indicator */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            marginBottom: 20 * s,
            zIndex: 10,
          }}
        >
          <div
            style={{
              fontSize: 52 * s,
              fontWeight: 800,
              color: textColor,
              lineHeight: 1,
            }}
          >
            12
          </div>
          <div
            style={{
              fontSize: 24 * s,
              fontWeight: 800,
              color: textColor,
              letterSpacing: 2 * s,
              marginTop: 4 * s,
            }}
          >
            HR
          </div>
          <svg
            width={40 * s}
            height={30 * s}
            viewBox="0 0 40 30"
            style={{ marginTop: 15 * s }}
          >
            <polygon points="0,0 40,0 20,30" fill={accentColor} />
          </svg>
        </div>

        {/* Dial Area */}
        <div
          style={{
            position: "relative",
            width: dialSize,
            height: dialSize,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            marginTop: -20 * s, // pull up slightly due to indicator
          }}
        >
          {/* Tick Marks */}
          <svg
            width={dialSize}
            height={dialSize}
            viewBox="-300 -300 600 600"
            style={{ position: "absolute", top: 0, left: 0 }}
          >
            {/* Dark inner groove line */}
            <circle
              cx={0}
              cy={0}
              r={240 * s / s}
              fill="none"
              stroke="rgba(0,0,0,0.05)"
              strokeWidth={4 * s / s}
            />
            
            {Array.from({ length: 12 }).map((_, i) => {
              const isMajor = i % 3 === 0;
              const tickLength = isMajor ? 35 : 20;
              const tickWidth = isMajor ? 6 : 4;
              return (
                <line
                  key={i}
                  x1={0}
                  y1={-280 + tickLength}
                  x2={0}
                  y2={-280}
                  transform={`rotate(${i * 30})`}
                  stroke={textColor}
                  strokeWidth={tickWidth}
                  strokeLinecap="round"
                />
              );
            })}
          </svg>

          {/* Side Labels */}
          <div
            style={{
              position: "absolute",
              left: -40 * s,
              top: "50%",
              transform: "translateY(-50%)",
              fontSize: 52 * s,
              fontWeight: 800,
              color: textColor,
            }}
          >
            9<span style={{ fontSize: 32 * s, marginLeft: 8 * s }}>-</span>
          </div>
          <div
            style={{
              position: "absolute",
              right: -40 * s,
              top: "50%",
              transform: "translateY(-50%)",
              fontSize: 52 * s,
              fontWeight: 800,
              color: textColor,
            }}
          >
            <span style={{ fontSize: 32 * s, marginRight: 8 * s }}>-</span>3
          </div>
          
          {/* Bottom Label */}
          <div
            style={{
              position: "absolute",
              bottom: -90 * s,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
            }}
          >
             <div style={{ width: 6*s, height: 20*s, backgroundColor: textColor, borderRadius: 3*s, marginBottom: 15*s }} />
            <div
              style={{
                fontSize: 52 * s,
                fontWeight: 800,
                color: textColor,
                lineHeight: 1,
              }}
            >
              6
            </div>
            <div
              style={{
                fontSize: 24 * s,
                fontWeight: 800,
                color: textColor,
                letterSpacing: 2 * s,
                marginTop: 4 * s,
              }}
            >
              HR
            </div>
          </div>

          {/* Rotating Knob */}
          <div
            style={{
              width: knobSize,
              height: knobSize,
              borderRadius: "50%",
              backgroundColor: panelColor,
              boxShadow: `
                0 ${20 * s}px ${30 * s}px rgba(0,0,0,0.15),
                0 ${5 * s}px ${10 * s}px rgba(0,0,0,0.1),
                inset 0 ${4 * s}px ${6 * s}px rgba(255,255,255,1),
                inset 0 -${4 * s}px ${8 * s}px rgba(0,0,0,0.05)
              `,
              border: `${2 * s}px solid rgba(0,0,0,0.03)`,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              transform: `rotate(${knobRotation}deg)`,
              // Center origin for precise rotation
              transformOrigin: "center center",
            }}
          >
            {/* Raised Handle */}
            <div
              style={{
                width: knobHandleWidth,
                height: knobHandleHeight,
                backgroundColor: panelColor,
                borderRadius: knobHandleWidth / 2,
                boxShadow: `
                  0 ${8 * s}px ${16 * s}px rgba(0,0,0,0.2),
                  0 ${2 * s}px ${4 * s}px rgba(0,0,0,0.1),
                  inset 0 ${3 * s}px ${6 * s}px rgba(255,255,255,1),
                  inset 0 -${2 * s}px ${4 * s}px rgba(0,0,0,0.05)
                `,
                border: `${1 * s}px solid rgba(255,255,255,0.5)`,
              }}
            />
          </div>
        </div>

        {/* Digital Display */}
        <div style={{ flex: 1 }} /> {/* Spacer */}
        
        <div
          style={{
            backgroundColor: backgroundColor, // Match main bg or use a slightly distinct dark tone
            width: 540 * s,
            height: 180 * s,
            borderRadius: 24 * s,
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            alignItems: "center",
            boxShadow: `inset 0 ${8 * s}px ${16 * s}px rgba(0,0,0,0.4), 0 ${2 * s}px ${4 * s}px rgba(255,255,255,0.8)`,
          }}
        >
          <div
            style={{
              fontSize: 72 * s,
              fontWeight: 700,
              color: "#ffffff",
              fontVariantNumeric: "tabular-nums",
              letterSpacing: 2 * s,
              lineHeight: 1.1,
            }}
          >
            {displayTime}
          </div>
          <div
            style={{
              fontSize: 22 * s,
              fontWeight: 700,
              color: "rgba(255,255,255,0.7)",
              letterSpacing: 4 * s,
            }}
          >
            HOURS
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default OvenTimer;